import itertools

def simulate(permutation, N, rounds=4):
    guests = list(range(N))
    tags = list(permutation)
    for r in range(rounds):
        remaining_indices = [i for i in range(len(guests)) if guests[i] != tags[i]]
        if not remaining_indices:
            return False
        new_guests = [guests[i] for i in remaining_indices]
        new_tags = [tags[i] for i in remaining_indices]
        m = len(new_tags)
        shifted_tags = [0] * m
        for i in range(m):
            shifted_tags[(i + 1) % m] = new_tags[i]
        guests = new_guests
        tags = shifted_tags
    return len(guests) > 0

for p in itertools.permutations(range(5)):
    if simulate(p, 5, 4):
        print(p)

