# But N! is too large. Let's use a random sample to estimate f(N, 4)/N!.
import random

def estimate_f(N, rounds, samples=100000):
    count = 0
    for _ in range(samples):
        p = list(range(N))
        random.shuffle(p)
        if simulate_all_exit(p, N, rounds):
            count += 1
    return count / samples

for N in range(5, 11):
    print(f"N={N}, estimate= {estimate_f(N, 4)}")
